double test_data::analytical_Br(const double omega)
{
   return 0.5*(0.1/(0.01+(0.5-omega)*(0.5-omega))+0.1/(0.01+(0.5+omega)*(0.5+omega)));
}

double test_data::analytical_K(const double tau)
{
   return exp(-0.1*tau)*cos(0.5*tau);
}

